remove_catalog_plugin() {
    REMOVE_KEY=$1
    # Detection comes from the receiver, never from A Panel installation history.
    opkg list-installed >/dev/null 2>&1 || {
        report 'CHECK: package database unavailable; no removal attempted.'
        return 2
    }
    if [ "$REMOVE_KEY" = aglare ] && grep -Eq '^config.skin.primary_skin=(Aglare-FHD|aglare)/' /etc/enigma2/settings 2>/dev/null; then
        report 'CHECK: active skin is in use. Select another skin before removing it.'
        return 2
    fi
    REMOVE_FOUND=0
    for REMOVE_PKG in $(plugin_package_candidates "$REMOVE_KEY"); do
        pkg_installed "$REMOVE_PKG" || continue
        REMOVE_FOUND=1
        opkg remove "$REMOVE_PKG" || return 1
        if pkg_installed "$REMOVE_PKG"; then
            report "FAILED: package still registered: $REMOVE_PKG"
            return 1
        fi
    done
    if [ "$REMOVE_FOUND" -eq 1 ]; then
        report 'Registered plugin package removed using opkg.'
        return 0
    fi
    # File-only installs: back up and remove only catalogued program folders.
    # Never remove dependencies, shared config, keys or unknown package files.
    REMOVE_DIRS=$(plugin_program_dirs "$REMOVE_KEY") || return 2
    REMOVE_BACKUP="/home/root/apanel-backups/${REMOVE_KEY}-$(date +%Y%m%d-%H%M%S)-$$"
    REMOVE_FOUND=0
    for REMOVE_DIR in $REMOVE_DIRS; do
        [ -d "$REMOVE_DIR" ] || continue
        if [ -L "$REMOVE_DIR" ]; then
            report "CHECK: linked program folder preserved: $REMOVE_DIR"
            return 2
        fi
        case "$REMOVE_DIR" in
            /usr/lib/enigma2/python/Plugins/Extensions/*|/usr/lib64/enigma2/python/Plugins/Extensions/*)
                if ! find "$REMOVE_DIR" -maxdepth 1 -type f \( -name plugin.py -o -name plugin.pyc -o -name plugin.pyo -o -name 'plugin*.so' \) | grep -q .; then
                    continue
                fi ;;
            /usr/share/enigma2/Aglare-FHD|/usr/share/enigma2/aglare)
                [ -f "$REMOVE_DIR/skin.xml" ] || continue
                if grep -Fq "config.skin.primary_skin=${REMOVE_DIR##*/}/skin.xml" /etc/enigma2/settings 2>/dev/null; then
                    report 'CHECK: active skin is in use. Select another skin before removing it.'
                    return 2
                fi ;;
            *) return 2 ;;
        esac
        if opkg search "$REMOVE_DIR/*" 2>/dev/null | grep -q ' - '; then
            report "CHECK: folder belongs to another package; preserved: $REMOVE_DIR"
            return 2
        fi
        umask 077
        mkdir -p "$REMOVE_BACKUP" || return 1
        chmod 700 "$REMOVE_BACKUP" || return 1
        cp -a "$REMOVE_DIR" "$REMOVE_BACKUP/" || return 1
        rm -rf "$REMOVE_DIR" || return 1
        REMOVE_FOUND=1
        report "Manual plugin folder removed. Backup: $REMOVE_BACKUP"
    done
    if [ "$REMOVE_FOUND" -eq 1 ]; then
        report 'Shared services and files outside the plugin folder were left in place.'
        return 0
    fi
    report 'CHECK: no registered package or supported manual program folder found.'
    return 2
}

remove_plugin_key() {
    case "$1" in
        ncam) remove_verified_cam ncam ;;
        oscamlevi) remove_verified_cam oscam ;;
        aj|subs|transmission|tmdb|arabicsavior|raed|audioshift|ipaudio|ipaudioplus|customcs|aglare|livefeed|epggrabber|xstreamity|mixaudio|mystreamer|furybiss|moviesostende)
            remove_catalog_plugin "$1" ;;
        *) report 'CHECK: unknown plugin; no files removed.'; return 2 ;;
    esac
}

run_mode() {
    MODE=$1
    [ -r "$CHOICES" ] || {
        say 'No plugin selection.'
        return 1
    }

    SELECTED=$(tr '\n' ' ' < "$CHOICES")
    COUNT=$(count_words "$SELECTED")
    TOTAL=$((COUNT + 1))
    NUM=0
    DONE=0
    OK=0
    CHECK=0
    FAIL=0

    : > "$PROGRESS"
    echo "$MODE" > "$MODEFILE"
    CAM_REMOVE_MODE=keep
    if [ "$MODE" = remove ] && [ -r "$REMOVE_OPTIONS" ]; then
        read -r CAM_REMOVE_MODE < "$REMOVE_OPTIONS"
        case "$CAM_REMOVE_MODE" in
            keep|clean) : ;;
            *) CAM_REMOVE_MODE=keep ;;
        esac
    fi

    if [ "$MODE" = install ]; then
        if ! begin_restart_guard; then
            end_restart_guard
            report 'FAILED: restart deferral could not be prepared; installation not started.'
            rm -f "$PIDFILE"
            return 1
        fi
        report "A Panel $VERSION | Install mode | $TOTAL steps"
        step 'Update OpenATV feed' opkg update
        # Display order is alphabetic; install order is deliberate.
        # AJ Panel is first. MixAudio, NCam and OSCam are the last three.
        # Child installer restart commands are deferred until the final reboot.
        for K in aj subs transmission tmdb arabicsavior raed audioshift ipaudioplus ipaudio customcs aglare livefeed epggrabber xstreamity mystreamer moviesostende furybiss mixaudio ncam oscamlevi; do
            case " $SELECTED " in
                *" $K "*) : ;;
                *) continue ;;
            esac
            NAME=$(plugin_name "$K")
            [ -n "$NAME" ] || continue
            step "$NAME" install_plugin_key "$K"
        done
        report '=== INSTALL FINISHED ==='
        report 'Full receiver reboot in 5 seconds.'
    else
        report "A Panel $VERSION | Uninstall mode | $TOTAL steps"
        step 'Refresh package status' true
        for K in $SELECTED; do
            NAME=$(plugin_name "$K")
            [ -n "$NAME" ] || continue
            step "Remove $NAME" remove_plugin_key "$K"
        done
        report '=== UNINSTALL PASS COMPLETE (CHECK means skipped) ==='
        report 'Restarting Enigma2 in 5 seconds (verified removals only).'
    fi

    bar
    report "Results: OK=$OK CHECK=$CHECK FAILED=$FAIL"
    report "Full log: $LOG"

    sync
    sleep 5
    rm -f "$PIDFILE"
    if [ "$MODE" = install ]; then
        # Restore real commands before issuing our single final receiver reboot.
        end_restart_guard
        reboot
    else
        init 4
        sleep 3
        init 3
    fi
}

plugin_name() {
    case "$1" in
        aj) echo 'AJ Panel' ;;
        subs) echo 'SubsSupport Pro' ;;
        transmission) echo 'Transmission' ;;
        tmdb) echo 'TMDB' ;;
        arabicsavior) echo 'Arabic Savior' ;;
        raed) echo 'Raed Quick Signal' ;;
        audioshift) echo 'AudioShift (Dreambox One only)' ;;
        ipaudio) echo 'IPAudio Pro' ;;
        ipaudioplus) echo 'IPAudio Plus' ;;
        customcs) echo 'Custom Channel Selection' ;;
        aglare) echo 'Aglare Skin' ;;
        livefeed) echo 'LiveFeed' ;;
        epggrabber) echo 'EPG Grabber' ;;
        xstreamity) echo 'XStreamity (OpenATV feed)' ;;
        mixaudio) echo 'MixAudio' ;;
        ncam) echo 'NCam' ;;
        oscamlevi) echo 'OSCam' ;;
        mystreamer) echo 'MyStreamer' ;;
        furybiss) echo 'FuryBiss' ;;
        moviesostende) echo 'Movies & Series Ostende' ;;
        *) echo '' ;;
    esac
}

if [ "${1:-}" = '--run-install' ]; then
    [ "$(id -u)" -eq 0 ] && command -v opkg >/dev/null 2>&1 || exit 1
    run_mode install
    exit $?
fi

if [ "${1:-}" = '--run-remove' ]; then
    [ "$(id -u)" -eq 0 ] && command -v opkg >/dev/null 2>&1 || exit 1
    run_mode remove
    exit $?
fi

if [ "$(id -u)" -ne 0 ] || ! command -v opkg >/dev/null 2>&1; then
    say 'ERROR: Root and OpenATV/opkg required'
    exit 1
fi

if ! command -v python3 >/dev/null 2>&1; then
    say 'ERROR: Python3 required'
    exit 1
fi

# Open the menu without restarting an already loaded GUI.
if [ -r "$READY" ]; then
    read -r UI_VERSION UI_PID < "$READY"
    if [ "$UI_VERSION" = "$VERSION" ] && [ -n "$UI_PID" ] && kill -0 "$UI_PID" 2>/dev/null; then
        : > "$REQUEST"
        say "A Panel $VERSION: opening the TV menu now."
        exit 0
    fi
fi

# New installation or GUI plugin update.
mkdir -p "$ROOT" "$PLUG" || exit 1
cp "$0" "$CORE" || exit 1
chmod 755 "$CORE"

