UPDATE_LOG = '/home/root/apanel-update.log'
REPO_INSTALL = 'https://raw.githubusercontent.com/hhawwas7/APanel/main/install.sh'

# Visual grouping only; the core shell has a separate, safety-conscious order.
GROUPS = [
    ('Panels', ['aj']),
    ('EMUs', ['ncam', 'oscamlevi']),
    ('Feed Hunters', ['furybiss', 'livefeed']),
    ('Audio', ['audioshift', 'ipaudioplus', 'ipaudio', 'mixaudio']),
    ('Media', ['moviesostende', 'mystreamer', 'tmdb', 'transmission', 'xstreamity']),
    ('EPG', ['customcs', 'epggrabber']),
    ('Subtitles', ['subs']),
    ('Skins', ['aglare']),
    ('Other Plugins', ['arabicsavior', 'raed']),
]
NAMES = {
    'aj': 'AJ Panel', 'ncam': 'NCam', 'oscamlevi': 'OSCam',
    'furybiss': 'FuryBiss', 'livefeed': 'LiveFeed',
    'audioshift': 'AudioShift', 'ipaudioplus': 'IPAudio Plus', 'ipaudio': 'IPAudio Pro', 'mixaudio': 'MixAudio',
    'moviesostende': 'Movies & Series\nOstende', 'mystreamer': 'MyStreamer',
    'tmdb': 'TMDB', 'transmission': 'Transmission', 'xstreamity': 'XStreamity',
    'customcs': 'Custom Channel\nSelection', 'epggrabber': 'EPG Grabber',
    'subs': 'SubsSupport\nPro', 'aglare': 'Aglare Skin',
    'arabicsavior': 'Arabic Savior', 'raed': 'Raed Quick\nSignal',
}
ALL_KEYS = [key for _, keys in GROUPS for key in keys]

# Exact registered packages, plus distinctive program files/directories.
# A saved configuration alone must NEVER count as Installed.
PACKAGE_IDS = {'aj': ['enigma2-plugin-extensions-ajpanel'], 'ncam': ['enigma2-plugin-softcams-ncam'], 'oscamlevi': ['enigma2-plugin-softcams-oscam-emu-pcsc-levi45'], 'furybiss': ['enigma2-plugin-extensions-furybiss', 'enigma2-plugin-extensions-furybis'], 'livefeed': ['enigma2-plugin-extensions-livefeed'], 'audioshift': ['enigma2-plugin-extensions-audioshift'], 'ipaudio': ['enigma2-plugin-extensions-ipaudiopro'], 'ipaudioplus': ['enigma2-plugin-extensions-ipaudioplus'], 'mixaudio': ['enigma2-plugin-extensions-mixaudio'], 'moviesostende': ['enigma2-plugin-extensions-moviesmanager'], 'mystreamer': ['enigma2-plugin-extensions-mystreamer'], 'tmdb': ['enigma2-plugin-extensions-tmdb', 'enigma2-plugin-extensions-tmbd'], 'transmission': ['enigma2-plugin-extensions-transmission', 'enigma2-plugin-extensions-transmission-e2'], 'xstreamity': ['enigma2-plugin-extensions-xstreamity'], 'customcs': ['enigma2-plugin-extensions-customchannelselection'], 'epggrabber': ['enigma2-plugin-extensions-epggrabber'], 'subs': ['enigma2-plugin-extensions-subssupportpro', 'enigma2-plugin-extensions-subsupportpro'], 'aglare': ['enigma2-plugin-skins-aglare-fhd', 'enigma2-plugin-skins-aglare'], 'arabicsavior': ['enigma2-plugin-extensions-arabicsavior'], 'raed': ['enigma2-plugin-extensions-raedquicksignal']}
# Distinctive paths only. Avoid generic shared config and key directories.
PLUGIN_PATHS = {'aj': ['/usr/lib/enigma2/python/Plugins/Extensions/AjPanel'], 'ncam': ['/usr/bin/ncam', '/usr/bin/NCam'], 'oscamlevi': ['/usr/bin/OSCam_11968-803'], 'furybiss': ['/usr/lib/enigma2/python/Plugins/Extensions/FuryBiss'], 'livefeed': ['/usr/lib/enigma2/python/Plugins/Extensions/LiveFeed', '/usr/lib/enigma2/python/Plugins/Extensions/LiveFeedOE', '/usr/lib/enigma2/python/Plugins/Extensions/LiveFe_ed'], 'audioshift': ['/usr/lib/enigma2/python/Plugins/Extensions/AudioShift'], 'ipaudio': ['/usr/lib/enigma2/python/Plugins/Extensions/IPAudioPro'], 'ipaudioplus': ['/usr/lib/enigma2/python/Plugins/Extensions/IPAudioPlus'], 'mixaudio': ['/usr/lib/enigma2/python/Plugins/Extensions/MixAudio'], 'moviesostende': ['/usr/lib/enigma2/python/Plugins/Extensions/MoviesManager'], 'mystreamer': ['/usr/lib/enigma2/python/Plugins/Extensions/MyStreamer'], 'tmdb': ['/usr/lib/enigma2/python/Plugins/Extensions/TMDB', '/usr/lib/enigma2/python/Plugins/Extensions/TMBD'], 'transmission': ['/usr/lib/enigma2/python/Plugins/Extensions/Transmission_e2', '/usr/lib/enigma2/python/Plugins/Extensions/Transmission'], 'xstreamity': ['/usr/lib/enigma2/python/Plugins/Extensions/XStreamity'], 'customcs': ['/usr/lib/enigma2/python/Plugins/Extensions/CustomChannelSelection'], 'epggrabber': ['/usr/lib/enigma2/python/Plugins/Extensions/EPGGrabber'], 'subs': ['/usr/lib/enigma2/python/Plugins/Extensions/SubsSupportPro'], 'aglare': ['/usr/share/enigma2/Aglare-FHD', '/usr/share/enigma2/aglare'], 'arabicsavior': ['/usr/lib/enigma2/python/Plugins/Extensions/ArabicSavior'], 'raed': ['/usr/lib/enigma2/python/Plugins/Extensions/RaedQuickSignal', '/usr/lib64/enigma2/python/Plugins/Extensions/RaedQuickSignal']}


def program_present(path):
    if '/Plugins/' in path:
        if not os.path.isdir(path): return False
        try:
            return any(name in ('plugin.py', 'plugin.pyc', 'plugin.pyo') or
                       (name.startswith('plugin') and name.endswith('.so'))
                       for name in os.listdir(path)
                       if os.path.isfile(os.path.join(path, name)))
        except OSError:
            return False
    if path.startswith('/usr/share/enigma2/'):
        return os.path.isfile(os.path.join(path, 'skin.xml'))
    return os.path.isfile(path) and os.access(path, os.X_OK)


def is_one():
    # Keep the original helper name to avoid changing unrelated callers.
    # AudioShift supports Dreambox One and Dreambox Two receivers.
    try:
        with open('/proc/stb/info/model') as f:
            model = ''.join(c for c in f.read().strip().lower() if c.isalnum())
            return model in ('one', 'two', 'dreamone', 'dreamtwo',
                             'dreamboxone', 'dreamboxtwo', 'dmone', 'dmtwo')
    except Exception:
        return False


def active():
    try:
        with open(PIDFILE) as f:
            pid = int(f.read().strip())
        os.kill(pid, 0)
        return True
    except Exception:
        return False


def current_mode():
    try:
        with open(MODEFILE) as f:
            return f.read().strip() or 'install'
    except Exception:
        return 'install'


def receiver_size():
    try:
        sz = getDesktop(0).size()
        w, h = sz.width(), sz.height()
        if 800 <= w <= 4096 and 480 <= h <= 2160:
            return w, h
    except Exception:
        pass
    return 1280, 720


def geometry():
    w, h = receiver_size()
    f = min(float(w) / 1280.0, float(h) / 720.0)
    return w, h, f, int((w - 1280 * f) / 2), int((h - 720 * f) / 2)


def coords(x, y, f, ox, oy):
    return ox + int(round(x * f)), oy + int(round(y * f))


def box(name, x, y, w, h, f, ox, oy, **kw):
    xx, yy = coords(x, y, f, ox, oy)
    # All widgets must paint ABOVE the full-screen static background ePixmap.
    # Default z=0 is theme-dependent and previously caused an empty-screen view.
    if 'zPosition' not in kw:
        kw['zPosition'] = '3'
    args = ' '.join('%s="%s"' % (k, v) for k, v in kw.items())
    return '<widget name="%s" position="%d,%d" size="%d,%d" %s />' % (
        name, xx, yy, int(round(w * f)), int(round(h * f)), args)


def bgname(w):
    return ASSETS + ('/background_1920.png' if w >= 1600 else '/background_1280.png')


# One continuous grid; category shortcuts never filter or toggle selection.
CARD_W, CARD_H = 130, 112
GAP_X, GAP_Y, HEADING_H = 20, 10, 0
GRID_COLS = 8
LEFT_MARGIN = (1280 - (GRID_COLS * CARD_W + (GRID_COLS - 1) * GAP_X)) // 2
VIEW_TOP, VIEW_BOTTOM = 142, 630
VIEW_HEIGHT = VIEW_BOTTOM - VIEW_TOP
DISPLAY_GROUP_ORDER = ('Panels', 'Audio', 'Media', 'Feed Hunters', 'EPG',
                       'Subtitles', 'Skins', 'EMUs', 'Other Plugins')
TAB_LABELS = ('Panels', 'Audio', 'Media', 'Feeds', 'EPG',
              'Subtitles', 'Skins', 'EMUs', 'Others')
TAB_LEFT, TAB_TOP, TAB_W, TAB_H, TAB_GAP = 50, 73, 124, 36, 8


def sections_layout(visible_keys=None):
    allowed = set(ALL_KEYS if visible_keys is None else visible_keys)
    grouped = dict(GROUPS)
    cards = []
    for title in DISPLAY_GROUP_ORDER:
        for key in grouped.get(title, ()):
            if key not in allowed: continue
            j = len(cards)
            col, row = j % GRID_COLS, j // GRID_COLS
            cards.append({'key': key, 'category': title,
                          'x': LEFT_MARGIN + col * (CARD_W + GAP_X),
                          'y': row * (CARD_H + GAP_Y), 'row': row})
    height = cards[-1]['y'] + CARD_H if cards else 0
    return cards, [], height


CARDS, HEADERS, VIRTUAL_HEIGHT = sections_layout()


def picker_skin():
    w,h,f,ox,oy=geometry()
    s=['<screen name="APanelGrid" position="0,0" size="%d,%d" flags="wfNoBorder" backgroundColor="#08131c">'%(w,h)]
    s.append('<ePixmap position="0,0" size="%d,%d" pixmap="%s" scale="1" alphatest="blend" zPosition="-20" />'%(w,h,bgname(w)))
    hx,hy=coords(24,4,f,ox,oy)
    s.append('<eLabel position="%d,%d" size="%d,%d" backgroundColor="#12242b" zPosition="1" />'%(
        hx,hy,int(round(1230*f)),int(round(59*f))))
    hx,hy=coords(26,63,f,ox,oy)
    s.append('<eLabel position="%d,%d" size="%d,%d" backgroundColor="#415b64" zPosition="2" />'%(
        hx,hy,int(round(1224*f)),max(1,round(f))))
    s.append(box('brandlogo',32,7,135,54,f,ox,oy,
                 transparent='1',alphatest='blend',scale='1',zPosition='5'))
    s.append(box('author',200,12,540,40,f,ox,oy,
                 font=UI_FONT+';%d'%round(25*f),foregroundColor='#d0e4ee',
                 transparent='1',valign='center',shadowOffset='0,0',borderWidth='0',zPosition='5'))
    s.append(box('selected_count',821,14,210,36,f,ox,oy,
                 font=UI_FONT+';%d'%round(20*f),foregroundColor='#a2ffcf',
                 backgroundColor='#163c35',borderWidth='0',shadowOffset='0,0',
                 halign='center',valign='center',zPosition='5'))
    s.append(box('plugins_count',1055,14,181,36,f,ox,oy,
                 font=UI_FONT+';%d'%round(20*f),foregroundColor='#c5e8ff',
                 backgroundColor='#173348',borderWidth='0',shadowOffset='0,0',
                 halign='center',valign='center',zPosition='5'))
    # Single full-width board. NO central divider / independent half-columns.
    s.append(box('bar',16,88,1248,555,f,ox,oy,zPosition='1',transparent='1'))
    for i, label in enumerate(TAB_LABELS):
        s.append(box('tab%d'%i,TAB_LEFT+i*(TAB_W+TAB_GAP),TAB_TOP,TAB_W,TAB_H,f,ox,oy,
                     font=UI_FONT+';%d'%round(18*f),foregroundColor='#c8dce5',
                     shadowOffset='0,0',
                     backgroundColor='#102631',borderWidth='0',
                     halign='center',valign='center',zPosition='5'))
    s.append(box('detection',50,112,1180,24,f,ox,oy,
                 font=UI_FONT+';%d'%round(15*f),foregroundColor='#a9c9d4',
                 transparent='1',halign='center',valign='center',zPosition='5'))
    for i,item in enumerate(CARDS):
        s.append(box('tile%d'%i,0,105,CARD_W,CARD_H,f,ox,oy,
                     zPosition='2',backgroundColor='#0b2027',borderColor='#285367',
                     borderWidth=str(max(1,round(f)))))
        # Cropped symbols appear at consistent apparent size regardless of original dark padding.
        s.append(box('icon%d'%i,0,105,84,60,f,ox,oy,
                     transparent='1',alphatest='blend',scale='1',zPosition='4'))
        # Regular maps to nmsbd (bold) on OpenATV skin_default.
        name=NAMES[item['key']]
        textsize=14 if '\n' in name or len(name)>16 else 17
        s.append(box('name%d'%i,0,105,CARD_W-10,34,f,ox,oy,
                     font='Regular;%d'%round(textsize*f),foregroundColor='#ffffff',
                     shadowColor='#071018',shadowOffset='1,1',
                     transparent='1',halign='center',valign='center',zPosition='5'))
        s.append(box('tick%d'%i,0,105,30,23,f,ox,oy,
                     font='Regular;%d'%round(16*f),foregroundColor='#ffffff',
                     halign='center',valign='center',transparent='1',zPosition='6'))
    # Preserve v0.4.10 footer exactly: SIX same-height buttons in a single row.
    s.append('<eLabel position="%d,%d" size="%d,%d" backgroundColor="#08151e" zPosition="-1" />'%(
        *coords(25,651,f,ox,oy),int(round(1230*f)),int(round(62*f))))
    foot=[
        ('redkey',36,184,'#d72e39','#ffffff'),
        ('greenkey',232,184,'#79c793','#10251b'),
        ('yellowkey',428,184,'#eec126','#14171b'),
        ('bluekey',624,184,'#257fe6','#ffffff'),
        ('menukey',820,190,'#f3f5f7','#17222d'),
        ('infokey',1023,215,'#343d47','#f2f4f6'),
    ]
    for key,x,ww,bgcolor,textcolor in foot:
        bx,by=coords(x,661,f,ox,oy)
        s.append('<eLabel position="%d,%d" size="%d,%d" backgroundColor="%s" zPosition="3" />'%(
            bx,by,int(round(ww*f)),int(round(43*f)),bgcolor))
        if key == 'menukey':
            s.append(box(key,x+46,661,ww-52,43,f,ox,oy,
                         font='Regular;%d'%round(19*f),foregroundColor=textcolor,
                         borderWidth='0',shadowOffset='0,0',transparent='1',halign='center',valign='center',zPosition='5'))
        else:
            s.append(box(key,x,661,ww,43,f,ox,oy,
                         font='Regular;%d'%round((18 if key=='infokey' else 22)*f),foregroundColor=textcolor,
                         borderWidth='0',shadowOffset='0,0',transparent='1',halign='center',valign='center',zPosition='5'))
    for symbol,x in [('trash',845)]:
        s.append(box(symbol+'icon',x,671,25,25,f,ox,oy,
                     transparent='1',alphatest='blend',scale='1',zPosition='6'))
    s.append('</screen>')
    return '\n'.join(s)


def simple_skin(title):
    w,h,f,ox,oy=geometry()
    s=['<screen name="APanelDialog" position="0,0" size="%d,%d" flags="wfNoBorder" backgroundColor="#09141e">'%(w,h)]
    s.append('<ePixmap position="0,0" size="%d,%d" pixmap="%s" alphatest="blend" scale="1" zPosition="-20" />'%(w,h,bgname(w)))
    s.append(box('heading',44,94,1170,58,f,ox,oy,font=UI_FONT+';%d'%round(28*f),foregroundColor='#f8c771',backgroundColor='#091721',borderWidth='0',shadowOffset='0,0'))
    s.append(box('status',44,170,1170,410,f,ox,oy,font=UI_FONT+';%d'%round(22*f),foregroundColor='#ffffff',backgroundColor='#0b1b25',borderWidth='0',shadowOffset='0,0'))
    s.append(box('footer',44,630,1170,55,f,ox,oy,font=UI_FONT+';%d'%round(19*f),foregroundColor='#75f1b8',backgroundColor='#091721',borderWidth='0',shadowOffset='0,0'))
    s.append('</screen>')
    return '\n'.join(s)


class GridPicker(Screen):
    def __init__(self, session, mode):
        Screen.__init__(self, session)
        self.skin = picker_skin()
        self.mode = mode
        self.allowed = set(ALL_KEYS)
        self.default_allowed = set(self.allowed)
        if not is_one():
            self.default_allowed.discard('audioshift')
        self.checked = set()
        self.cursor = 0
        self.offset = 0
        self.tab_focus = False
        self.tab_cursor = 0
        self.states = {}
        self.evidence = {}
        self.entries = []
        self.layout_headers = HEADERS
        self.virtual_height = VIRTUAL_HEIGHT
        self.package_query_ok = False
        self._package_names = set()
        self['brandlogo'] = Pixmap()
        self['author'] = Label('Mr. Hamada Hawwas')
        self['selected_count'] = Label('')
        self['plugins_count'] = Label('')
        self['bar'] = Label('')
        for i, label in enumerate(TAB_LABELS):
            self['tab%d'%i] = Label('%d %s'%(i+1,label))
        self['detection'] = Label('')
        for i, item in enumerate(CARDS):
            for prefix, cls in (('tile',Label),('icon',Pixmap),('name',Label),('tick',Label)):
                self['%s%d'%(prefix,i)] = cls() if prefix != 'tile' else cls('')
            self['name%d'%i].setText(NAMES[item['key']])
        for key,text in (
            ('redkey','EXIT'),
            ('greenkey','INSTALL' if mode=='install' else 'REMOVE'),
            ('yellowkey','ALL'),('bluekey','NONE'),
            ('menukey','UNINSTALL' if mode=='install' else 'BACK'),('infokey','INFO: UPDATE PANEL')):
            self[key]=Label(text)
        self['trashicon']=Pixmap()
        self['actions']=ActionMap(
            ['OkCancelActions','DirectionActions','ColorActions','MenuActions','InfoActions','InfobarEPGActions','NumberActions'],
            {'up':lambda:self.navigate('up'),'down':lambda:self.navigate('down'),
             'left':lambda:self.navigate('left'),'right':lambda:self.navigate('right'),
             'ok':self.toggle,'green':self.execute,'yellow':self.all,'blue':self.none,
             'red':self.close,'cancel':self.close,'menu':self.change_mode,
             'info':self.show_updates,'showEventInfo':self.show_updates,
             **{str(i+1):(lambda index=i:self.jump_category(index)) for i in range(len(TAB_LABELS))}},-1)
        self.onLayoutFinish.append(self.on_ready)

    def scan(self):
        self.package_query_ok = False
        self._package_names = set()
        try:
            output = subprocess.check_output(['opkg','list-installed'])
            if not isinstance(output,str):
                output=output.decode('utf-8','ignore')
            self._package_names = set(line.split()[0] for line in output.splitlines() if line.strip())
            self.package_query_ok = True
        except Exception:
            pass
        self.states = {}
        self.evidence = {}
        for key in ALL_KEYS:
            packages = [p for p in PACKAGE_IDS.get(key,[]) if p in self._package_names]
            files = [p for p in PLUGIN_PATHS.get(key,[]) if program_present(p)]
            if packages:
                self.states[key] = 'Installed'
                self.evidence[key] = 'Installed package: ' + ', '.join(packages)
            elif files:
                self.states[key] = 'Installed'
                self.evidence[key] = 'Program files detected; no matching package record'
            elif self.package_query_ok:
                self.states[key] = 'Not Installed'
                self.evidence[key] = 'Not detected on this receiver'
            else:
                self.states[key] = 'Needs Verification'
                self.evidence[key] = 'Package database unavailable; installation could not be verified'

    def on_ready(self):
        for key, filename in (('trashicon','controls/trash.png'),('brandlogo','plugin.png')):
            try:
                self[key].instance.setPixmapFromFile(ASSETS+'/'+filename)
            except Exception:
                pass
        self.scan()
        keys=set(ALL_KEYS if self.mode=='install' else
                 [k for k in ALL_KEYS if self.states[k]=='Installed'])
        self.entries, self.layout_headers, self.virtual_height = sections_layout(keys)
        self.cursor = 0
        self.checked = (set(k for k in self.default_allowed if self.states.get(k)=='Not Installed')
                        if self.mode=='install' else set())
        for i,item in enumerate(CARDS):
            try:
                self['icon%d'%i].instance.setPixmapFromFile(ASSETS+'/icons/'+item['key']+'.png')
            except Exception:
                pass
        self.draw()

    def selected_card(self):
        if self.entries:
            return self.entries[min(self.cursor, len(self.entries)-1)]
        return None

    def move_widget(self,key,x,y):
        try:
            self[key].instance.move(ePoint(*coords(x,y,self._f,self._ox,self._oy)))
        except Exception:
            pass

    def draw(self):
        _,_,self._f,self._ox,self._oy=geometry()
        self['selected_count'].setText('%d Selected'%len(self.checked))
        self['plugins_count'].setText('%d Plugins'%len(self.entries))
        selected=self.selected_card()
        self['detection'].setText((NAMES[selected['key']].replace('\n',' ') + ' | ' + self.evidence.get(selected['key'],''))
            if selected else 'No supported plugins detected on this receiver.')
        if selected:
            cy=selected['y']
            if cy+CARD_H>self.offset+VIEW_HEIGHT:
                self.offset=cy+CARD_H-VIEW_HEIGHT+4
            if cy-HEADING_H<self.offset:
                self.offset=max(0,cy-HEADING_H-4)
            self.offset=max(0,min(self.offset,max(0,self.virtual_height-VIEW_HEIGHT)))
        selected_category = selected['category'] if selected else None
        available = set(card['category'] for card in self.entries)
        for i, title in enumerate(DISPLAY_GROUP_ORDER):
            focused = self.tab_focus and self.tab_cursor == i
            current = not self.tab_focus and selected_category == title
            try:
                tab = self['tab%d'%i].instance
                tab.setBackgroundColor(parseColor('#e6b944' if focused else '#21483e' if current else '#102631'))
                tab.setForegroundColor(parseColor('#15202a' if focused else '#eef3f5' if current else '#c8dce5' if title in available else '#657781'))
                tab.setBorderColor(parseColor('#ffe08b' if focused else '#63deb0' if current else '#345362'))
                tab.setBorderWidth(0)
            except Exception:
                pass
        by_key={card['key']:card for card in self.entries}
        for i,item in enumerate(CARDS):
            key=item['key']
            card=by_key.get(key)
            yy=VIEW_TOP+card['y']-self.offset if card else -999
            visible=bool(card and VIEW_TOP<=yy and yy+CARD_H<=VIEW_BOTTOM)
            for prefix in ('tile','icon','name','tick'):
                self['%s%d'%(prefix,i)].show() if visible else self['%s%d'%(prefix,i)].hide()
            if not visible:continue
            x=card['x']
            self.move_widget('tile%d'%i,x,yy)
            self.move_widget('icon%d'%i,x+(CARD_W-84)//2,yy+9)
            self.move_widget('name%d'%i,x+5,yy+76)
            self.move_widget('tick%d'%i,x+CARD_W-32,yy+1)
            focused=bool(not self.tab_focus and selected and selected['key']==key)
            chosen=(key in self.checked)
            # Whole-card yellow focus, independent [X]/[ ] selected status.
            bg = '#e6b944' if focused else ('#114235' if chosen else '#26333d')
            edge = '#ffe08b' if focused else ('#28cf91' if chosen else '#34576a')
            tick='[X]' if chosen else '[ ]'
            self['tick%d'%i].setText(tick)
            try:
                tile=self['tile%d'%i].instance
                tile.setBackgroundColor(parseColor(bg))
                tile.setBorderColor(parseColor(edge))
                tile.setBorderWidth(max(1,round((3 if focused else 2)*self._f)))
                self['tick%d'%i].instance.setForegroundColor(parseColor(
                    '#15202a' if focused else '#82ffcb' if chosen else '#8aa3b1'))
                self['name%d'%i].instance.setForegroundColor(parseColor(
                    '#15202a' if focused else '#ffffff'))
            except Exception:
                pass

    def jump_category(self, index):
        title = DISPLAY_GROUP_ORDER[index]
        for j, card in enumerate(self.entries):
            if card['category'] == title:
                self.cursor = j
                self.tab_cursor = index
                self.tab_focus = False
                self.draw()
                return
        # An empty uninstall category keeps the current card and selection.
        self.tab_cursor = index
        self.tab_focus = True
        self.draw()

    def navigate(self, direction):
        if self.tab_focus:
            if direction == 'left': self.tab_cursor = (self.tab_cursor-1) % len(TAB_LABELS)
            elif direction == 'right': self.tab_cursor = (self.tab_cursor+1) % len(TAB_LABELS)
            elif direction == 'down':
                self.jump_category(self.tab_cursor)
                return
            self.draw()
            return
        if not self.entries:
            self.tab_focus = True
            self.draw()
            return
        if direction == 'up' and self.cursor < GRID_COLS:
            self.tab_focus = True
            self.tab_cursor = DISPLAY_GROUP_ORDER.index(self.selected_card()['category'])
        elif direction == 'left': self.cursor = max(0,self.cursor-1)
        elif direction == 'right': self.cursor = min(len(self.entries)-1,self.cursor+1)
        elif direction == 'up': self.cursor = max(0,self.cursor-GRID_COLS)
        elif direction == 'down':
            if (self.cursor//GRID_COLS+1)*GRID_COLS < len(self.entries):
                self.cursor = min(len(self.entries)-1,self.cursor+GRID_COLS)
        self.draw()

    def toggle(self):
        if self.tab_focus:
            self.jump_category(self.tab_cursor)
            return
        item=self.selected_card()
        if item is None:return
        key=item['key']
        if self.mode=='install' and key == 'audioshift' and not is_one() and key not in self.checked:
            self.session.open(MessageBox,
                'AudioShift works correctly on Dreambox One and Dreambox Two devices.',
                MessageBox.TYPE_INFO, timeout=6)
            # Warn, but allow explicit selection on other receiver models.
        if self.mode=='install' and key not in self.allowed:
            return
        if key in self.checked:self.checked.remove(key)
        else:self.checked.add(key)
        self.draw()

    def all(self):
        self.checked=set(card['key'] for card in self.entries if self.mode=='uninstall' or
                         (card['key'] in self.allowed and self.states.get(card['key'])=='Not Installed'))
        self.draw()

    def none(self):
        self.checked=set()
        self.draw()

    def change_mode(self):
        if self.mode=='install':
            if active():self.session.open(TaskProgress)
            else:self.session.open(UninstallPicker)
        else:self.close()

    def show_updates(self):
        if active():self.session.open(TaskProgress)
        else:self.session.open(UpdateScreen)

    def execute(self):
        selected=set(self.checked)
        if not selected:
            self.session.open(MessageBox, 'Select at least one plugin first.', MessageBox.TYPE_INFO, timeout=5)
            return
        if active():
            self.session.open(TaskProgress)
            return
        if self.mode=='uninstall':
            self.cam_remove_mode = 'keep'
            if 'ncam' in selected or 'oscamlevi' in selected:
                self.session.openWithCallback(self.choose_cam_removal,ChoiceBox,
                    title='NCam / OSCam uninstall: choose how to handle their settings',
                    list=[('Remove EMU only — KEEP configuration', 'keep'),
                          ('Remove EMU + its own configuration (backup first)', 'clean'),
                          ('Cancel', 'cancel')])
            else:
                self.confirm_cam_removal()
        else:self.launch('install',selected)

    def choose_cam_removal(self,choice):
        if not choice or choice[1] == 'cancel': return
        self.cam_remove_mode = choice[1] if choice[1] in ('keep','clean') else 'keep'
        self.confirm_cam_removal()

    def confirm_cam_removal(self):
        total = len(self.checked)
        suffix = ''
        if 'ncam' in self.checked or 'oscamlevi' in self.checked:
            suffix = ('\nEMUs: keep cam settings.' if self.cam_remove_mode == 'keep'
                else '\nEMUs: remove their own settings after private backup.')
            suffix += '\nOnly supported package versions can be removed safely.'
        self.session.openWithCallback(self.confirm_remove,MessageBox,
            'Remove %d selected plugin(s)?\nManual plugin folders are backed up before removal.\nPackage uninstall rules apply to registered packages.%s'%(total,suffix),
            MessageBox.TYPE_YESNO,default=False)

    def confirm_remove(self,yes):
        if yes and not active():self.launch('remove',set(self.checked))

    def launch(self,mode,selected):
        try:
            with open(CHOICES,'w') as f:f.write('\n'.join(k for k in ALL_KEYS if k in selected)+'\n')
            if mode == 'remove':
                with open(REMOVE_OPTIONS,'w') as f:f.write(getattr(self,'cam_remove_mode','keep')+'\n')
            logfile=open(LOG,'w')
            try:
                proc=subprocess.Popen(['/bin/sh',CORE,'--run-'+mode],
                    stdin=subprocess.DEVNULL,stdout=logfile,stderr=subprocess.STDOUT,
                    close_fds=True,start_new_session=True)
            finally:logfile.close()
            with open(PIDFILE,'w') as f:f.write(str(proc.pid))
            with open(MODEFILE,'w') as f:f.write(mode+'\n')
            self.session.open(TaskProgress)
        except Exception as e:
            self.session.open(MessageBox, 'Start error: %s'%e, MessageBox.TYPE_ERROR, timeout=7)


class InstallPicker(GridPicker):
    def __init__(self,session):GridPicker.__init__(self,session,'install')


class UninstallPicker(GridPicker):
    def __init__(self,session):GridPicker.__init__(self,session,'uninstall')


class TaskProgress(Screen):
    def __init__(self,session):
        Screen.__init__(self,session)
        self.skin=simple_skin('Progress')
        self['heading']=Label('A Panel  |  Working')
        self['status']=Label('Preparing...')
        self['footer']=Label('Telnet can be closed; task continues. RED/EXIT closes this view.')
        self['actions']=ActionMap(['OkCancelActions','ColorActions'],
            {'ok':self.close,'cancel':self.close,'red':self.close},-1)
        self.timer=eTimer()
        try:self.timer.callback.append(self.update)
        except AttributeError:self.timer_connection=self.timer.timeout.connect(self.update)
        self.onShown.append(self.begin)
        self.onClose.append(self.stop)

    def begin(self):
        self.update()
        self.timer.start(1500,False)

    def stop(self):self.timer.stop()

    def update(self):
        self['heading'].setText('A Panel   |   %s'%('Installing' if current_mode()=='install' else 'Uninstalling'))
        try:
            with open(PROGRESS) as f:
                text='\n'.join(f.read().splitlines()[-12:])
            self['status'].setText(text or 'Preparing...')
        except Exception:self['status'].setText('Preparing...')


def version_tuple(v):
    parts=re.findall(r'\d+',v or '')
    return tuple(int(s) for s in parts[:4])


class UpdateScreen(Screen):
    def __init__(self,session):
        Screen.__init__(self,session)
        self.skin=simple_skin('Updates')
        self['heading']=Label('A Panel  |  Check for Updates')
        self['status']=Label('Checking GitHub for a newer A Panel version...')
        self['footer']=Label('GREEN: Update (only when available)   RED: Back')
        self['actions']=ActionMap(['OkCancelActions','ColorActions'],
            {'green':self.want_update,'red':self.close,'cancel':self.close},-1)
        self.timer=eTimer()
        try:self.timer.callback.append(self.poll)
        except AttributeError:self.timer_connection=self.timer.timeout.connect(self.poll)
        self.proc=None
        self.remote_version=None
        self.ready=False
        self.checked_once=False
        self.onShown.append(self.check)
        self.onClose.append(self.timer.stop)

    def check(self):
        if self.checked_once:return
        self.checked_once=True
        if active():
            self['status'].setText('Installation or removal is already in progress.')
            return
        try:
            if os.path.exists(UPDATE_FILE):os.unlink(UPDATE_FILE)
            self.proc=subprocess.Popen(['wget','-q','-T','15','-t','2','-O',UPDATE_FILE,REPO_INSTALL],
                stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
            self.timer.start(1200,False)
        except Exception as e:self['status'].setText('Unable to start update check: %s'%e)

    def poll(self):
        if self.proc is None:return
        if self.proc.poll() is None:return
        self.timer.stop()
        if self.proc.returncode!=0:
            self['status'].setText('No update check possible. Check internet and GitHub.')
            return
        try:
            with open(UPDATE_FILE,'rb') as f:
                src=f.read(2500000)
            if not src.startswith(b'#!/bin/sh'):
                raise ValueError('Unexpected file header')
            match=re.search(rb'(?m)^VERSION=(v[0-9][0-9.]*)\s*$',src[:9000])
            if not match:raise ValueError('Unable to read version')
            self.remote_version=match.group(1).decode('ascii')
            if version_tuple(self.remote_version) > version_tuple(VERSION):
                self.ready=True
                self['status'].setText('Current version: %s\nNew version: %s\n\nGREEN to update A Panel only.\nInstalled plugins will NOT be reinstalled.'%(VERSION,self.remote_version))
            else:
                self['status'].setText('Current version: %s\nGitHub version: %s\n\nA Panel is already up to date.'%(VERSION,self.remote_version))
        except Exception as e:
            self['status'].setText('Update data could not be verified: %s'%e)

    def want_update(self):
        if not self.ready or active():return
        self.session.openWithCallback(self.start_update,MessageBox,
            'Update A Panel from %s to %s?\nThis will restart Enigma2 GUI once.'%(VERSION,self.remote_version),
            MessageBox.TYPE_YESNO,default=False)

    def start_update(self,confirmed):
        if not confirmed or active():return
        try:
            check=subprocess.call(['/bin/sh','-n',UPDATE_FILE])
            if check!=0:raise ValueError('Installer syntax check failed')
            logfile=open(UPDATE_LOG,'w')
            try:
                subprocess.Popen(['/bin/sh',UPDATE_FILE],stdin=subprocess.DEVNULL,
                    stdout=logfile,stderr=subprocess.STDOUT,close_fds=True,start_new_session=True)
            finally:logfile.close()
            self['status'].setText('A Panel update launched.\nGUI will restart when the update completes.')
            self.ready=False
        except Exception as e:
            self['status'].setText('Update failed to start: %s'%e)


_session=None
_poll=None
_poll_conn=None
_opening=False


def poll_request():
    global _opening
    if _session is None or _opening or not os.path.exists(REQUEST):return
    _opening=True
    try:
        os.unlink(REQUEST)
        _session.open(TaskProgress if active() else InstallPicker)
    except Exception as e:
        print('[A Panel] Open error:',e)
        try:open(REQUEST,'w').close()
        except Exception:pass
    finally:_opening=False


def session_start(reason,**kwargs):
    global _session,_poll,_poll_conn
    if reason!=0 or 'session' not in kwargs:return
    _session=kwargs['session']
    _poll=eTimer()
    try:_poll.callback.append(poll_request)
    except AttributeError:_poll_conn=_poll.timeout.connect(poll_request)
    _poll.start(1500,False)
    try:
        with open(READY,'w') as f:f.write('%s %d\n'%(VERSION,os.getpid()))
    except Exception:pass
    if active() and not os.path.exists(REQUEST):
        try:open(REQUEST,'w').close()
        except Exception:pass


def open_plugin(session,**kwargs):
    session.open(TaskProgress if active() else InstallPicker)


def Plugins(**kwargs):
    return [PluginDescriptor(name='APanel',description='Mr. Hamada Hawwas',
            icon='plugin.png',where=PluginDescriptor.WHERE_PLUGINMENU,fnc=open_plugin),
            PluginDescriptor(where=PluginDescriptor.WHERE_SESSIONSTART,fnc=session_start)]

PY

# Built-in syntax check, no py_compile module needed.
python3 -c 'import sys; p=sys.argv[1]; compile(open(p,"rb").read(),p,"exec"); print("Python syntax OK")' "$PLUG/plugin.py" || {
    say 'ERROR: A Panel Python syntax failed'
    exit 1
}

touch "$PLUG/__init__.py" || exit 1

# Remove only the previous panel's loader after new plugin syntax has passed.
# Other plugins or their data are never touched here.
OLD_PLUG=/usr/lib/enigma2/python/Plugins/Extensions/HawwasInstaller
if [ -d "$OLD_PLUG" ]; then
    rm -rf "$OLD_PLUG" || {
        say 'WARNING: Could not remove previous Hawwas Panel menu entry.'
    }
fi

: > "$REQUEST"

say "A Panel $VERSION installed/updated."
say 'Restarting Enigma2 GUI once to load this version.'
say 'Future launches of this version will not restart GUI.'
say 'Remote: UP/DOWN, OK toggle, GREEN install, MENU uninstall.'

nohup sh -c 'sleep 2; init 4; sleep 3; init 3' > /home/root/apanel-launch.log 2>&1 < /dev/null &
exit 0
